audit.cssChanges:
/* U06: preserve existing pause geometry and sizes while using the common blue frame. */
#interface .pause-actions .game-button{font-family:inherit;font-weight:600}
#interface .pause-actions .pause-return{font-size:12px;min-height:40px;padding:6px 12px}
@container game (max-width:600px){#interface .pause-actions .pause-return{font-size:11px}}
@container game (max-height:560px) and (min-width:601px){#interface .pause-actions .pause-return{min-height:29px;font-size:10px}}
.settings-body .save-actions{display:flex;flex-wrap:wrap;gap:10px}
